pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address k) public {
        vm.assume(k != address(0));

        address owner = c.owner();
        vm.prank(owner);
        c.setKeeper(k);

        assertTrue(c.keeper() == k);
    }
}
